const self = this; // Store the context
const allData = this.getValues();

if(arguments[0].value) {
  this.setData({
    'parent_material_name': arguments[0].fieldModel.item.material_name,
    'parent_material_category': arguments[0].fieldModel.item.item_category,
    'parent_material_desc': arguments[0].fieldModel.item.material_desc,
    [`subform_sub_material`] : [],
    'parent_mat_base_quantity': 1,
    'parent_mat_is_default': 0,
    'parent_mat_base_uom': arguments[0].fieldModel.item.based_uom
  });

  const materialId = allData.parent_material_code;

  db.collection("prefix_configuration")
    .where({
      document_types: "Bill Of Materials",
      is_active: 1
    })
    .get()
    .then((result) => {
      if (!result.data.length > 0) {
        console.log("result", result);
        this.setData({'parent_mat_bom_version': ''});
        return Promise.resolve(null);
      }
      return db.collection("bill_of_materials")
        .where({
          parent_material_code: materialId
        })
        //.orderBy("create_time", "desc") // Fetch latest records first
        .get();
    })
    .then(function(bomResult) {
      console.log("bomResult", bomResult);
      var highestVersion = 0;

      // Find the highest version number among the fetched records
      if (bomResult && bomResult.data.length > 0) {
        bomResult.data.forEach(record => {
          const version = record.parent_mat_bom_version;
          const versionMatch = version.match(/V(\d+)$/);
          if (versionMatch) {
            const versionNum = parseInt(versionMatch[1]);
            if (versionNum > highestVersion) {
              highestVersion = versionNum;
            }
          }
        });
      }

      // Increment to the next version
      const nextVersion = highestVersion + 1;
      var newMaterialCode = "V" + nextVersion;
      console.log("newMaterialCode", newMaterialCode);
      self.setData({'parent_mat_bom_version': newMaterialCode});
      return newMaterialCode;
    })
    .catch(function(error) {
      console.error("Error in material code generation:", error);
      throw error;
    });
} else {
  this.setData({
    parent_material_name: '',
    parent_material_category: '',
    parent_material_desc: '',
    parent_mat_bom_version: '',
    parent_mat_is_default: 0,
    parent_mat_base_quantity: 0,
    parent_mat_base_uom: '',
    subform_sub_material: []
  })
}

